"""Genera los .inc de NetSurf sin perl/gperf (v2.4.2)."""
import pathlib, re

NS = pathlib.Path("v2.0/thirdparty/netsurf")


def gen_entities():
    src = NS / "libhubbub-0.3.8/build/Entities"
    dst = NS / "libhubbub-0.3.8/src/tokeniser/entities.inc"
    entities = {}
    for line in src.read_text(encoding="utf-8", errors="replace").splitlines():
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        entities[parts[0]] = parts[1]
    out = ("/*\n * This file is part of Hubbub.\n * Licensed under the MIT License,\n"
           " *                http://www.opensource.org/licenses/mit-license.php\n"
           " * Copyright 2010 The NetSurf Project.\n *\n"
           " * Note: This file is automatically generated (python, v2.4.2)\n *\n"
           " * Do not edit file file, changes will be overwritten during build.\n */\n\n")
    heapindex = 0
    nodelist = []

    def insert(parent, key, code):
        nonlocal heapindex
        if len(key) == 0:
            pivot, tail = "", ""
        elif len(key) == 1:
            pivot, tail = key, ""
        else:
            pivot, tail = key[0], key[1:]
        if parent is None:
            parent = {"pivot": pivot, "heapindex": heapindex}
            nodelist.append(parent)
            heapindex += 1
        if pivot < parent["pivot"]:
            parent["lt"] = insert(parent.get("lt"), key, code)
        elif pivot == parent["pivot"]:
            if pivot == "":
                parent["value"] = code
            elif tail[:1] == "":
                parent["value"] = code
                parent["eq"] = insert(parent.get("eq"), tail, code)
            else:
                parent["eq"] = insert(parent.get("eq"), tail, code)
        else:
            parent["gt"] = insert(parent.get("gt"), key, code)
        return parent

    trie = None
    for key in sorted(entities):
        trie = insert(trie, key, entities[key])
    out += "static hubbub_entity_node dict[] = {\n"
    for node in nodelist:
        def idx(k):
            v = node.get(k)
            return str(v["heapindex"]) if v is not None else "-1"
        split = node["pivot"]
        splitv = str(ord(split)) if split != "" else "0"
        value = node.get("value", "0")
        out += "\t{ %s, %s, %s, %s, %s },\n" % (
            splitv, idx("lt"), idx("eq"), idx("gt"), value)
    out += "};\n\n"
    out += "static int32_t dict_root = %d;\n" % trie["heapindex"]
    dst.write_text(out, encoding="utf-8")
    print("entities.inc: %d entidades, %d nodos" % (len(entities), len(nodelist)))


def gen_aliases():
    src = NS / "libparserutils-0.2.5/build/Aliases"
    dst = NS / "libparserutils-0.2.5/src/charset/aliases.inc"
    charsets = {}
    order = []
    for line in src.read_text(encoding="utf-8", errors="replace").splitlines():
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        canon, mib = parts[0], parts[1]
        charsets[canon] = (mib, parts[2:])
        order.append(canon)
    out = ("/*\n * This file is part of LibParserUtils.\n * Licensed under the MIT License,\n"
           " *                http://www.opensource.org/licenses/mit-license.php\n"
           " * Copyright 2010 The NetSurf Project.\n *\n"
           " * Note: This file is automatically generated (python, v2.4.2)\n *\n"
           " * Do not edit file file, changes will be overwritten during build.\n */\n\n"
           "static parserutils_charset_aliases_canon canonical_charset_names[] = {\n")
    uni = re.compile(r"^(ISO-10646-UCS-[24]|UTF-16|UTF-8$|UTF-32)")
    unicodeexp = ""
    aliases = {}
    canonnr = 0
    for canon in sorted(charsets):
        mib, elements = charsets[canon]
        out += "\t{ %s, %d, \"%s\" },\n" % (mib, len(canon), canon)
        if uni.match(canon):
            unicodeexp += "((x) == %s) || " % mib
        norm = re.sub(r"[^a-z0-9]", "", canon.lower())
        aliases[norm] = canonnr
        for a in elements:
            na = re.sub(r"[^a-z0-9]", "", a.lower())
            aliases[na] = canonnr
        canonnr += 1
    out += "};\n\nstatic const uint16_t charset_aliases_canon_count = %d;\n\n" % canonnr
    out += ("typedef struct {\n\tuint16_t name_len;\n\tconst char *name;\n"
            "\tparserutils_charset_aliases_canon *canon;\n"
            "} parserutils_charset_aliases_alias;\n\n"
            "static parserutils_charset_aliases_alias charset_aliases[] = {\n")
    aliascount = 0
    for alias in sorted(aliases):
        out += "\t{ %d, \"%s\", &canonical_charset_names[%d] },\n" % (
            len(alias), alias, aliases[alias])
        aliascount += 1
    out += "};\n\n"
    unicodeexp = unicodeexp[:-4] if unicodeexp.endswith(" || ") else "0"
    out += ("static const uint16_t charset_aliases_count = %d;\n\n"
            "#define MIBENUM_IS_UNICODE(x) (%s)\n") % (aliascount, unicodeexp)
    dst.write_text(out, encoding="utf-8")
    print("aliases.inc: %d canon, %d alias" % (canonnr, aliascount))


def gen_element_type():
    src = NS / "libhubbub-0.3.8/src/treebuilder/element-type.gperf"
    dst = NS / "libhubbub-0.3.8/src/treebuilder/autogenerated-element-type.c"
    pairs = []
    for line in src.read_text(encoding="utf-8", errors="replace").splitlines():
        m = re.match(r"^([a-z0-9-]+),\s+([A-Z_0-9]+)$", line.strip())
        if m:
            pairs.append((m.group(1), m.group(2)))
    out = ("/* Auto-generated by python (v2.4.2) from element-type.gperf.\n"
           " * Replaces gperf output: same symbols, linear lookup.\n */\n"
           "#include <string.h>\n"
           "#include <strings.h>\n"
           "#include \"treebuilder/element-type.h\"\n\n"
           "struct element_type_map { const char *name; element_type type; };\n\n"
           "static const struct element_type_map wordlist[] = {\n")
    for name, typ in pairs:
        out += '\t{ "%s", %s },\n' % (name, typ)
    out += ("};\n\n"
            "static unsigned hubbub_element_type_generated_hash(const char *s, unsigned n)\n"
            "{ unsigned h = 0; while (n--) h = h * 33 + (unsigned char)*s++; return h; }\n\n"
            "static const struct element_type_map *hubbub_element_type_generated_lookup(const char *s, unsigned n)\n"
            "{\n\tsize_t i;\n\tfor (i = 0; i < sizeof(wordlist)/sizeof(wordlist[0]); i++) {\n"
            "\t\tif (strlen(wordlist[i].name) == n && strncasecmp(wordlist[i].name, s, n) == 0)\n"
            "\t\t\treturn &wordlist[i];\n\t}\n\treturn NULL;\n}\n")
    dst.write_text(out, encoding="utf-8")
    print("autogenerated-element-type.c: %d elementos" % len(pairs))


gen_entities()
gen_aliases()
gen_element_type()
